import{resolveModelApiKey}from"./api-key.js";import{readVercelCliConnection,refreshVercelCliConnection}from"./vercel-cli.js";import{resolveVercelSession}from"./vercel.js";import{MODEL_CONNECTION_ENV}from"#shared/model-helper.js";import{getVercelOidcToken}from"#compiled/@vercel/oidc/index.js";async function resolveGatewayModelCredential(e){let t=process.env[MODEL_CONNECTION_ENV];if(t===`vercel`||t===`vercel-cli`){t===`vercel-cli`&&e&&await refreshVercelCliConnection();let n=t===`vercel`?await resolveVercelSession(e):await readVercelCliConnection();if(!n)throw Error(`Vercel CLI credentials are unavailable. Run /login.`);return{kind:`oauth`,token:`accessToken`in n?n.accessToken:n.token,teamId:process.env.EVE_MODEL_TEAM??n.teamId,teamName:process.env.EVE_MODEL_TEAM_NAME??(`teamName`in n?n.teamName:n.teamId)}}return t===`ai-gateway-key`?{kind:`api-key`,token:await resolveModelApiKey(`ai-gateway-key`)}:t!==`ai-gateway-project`&&process.env.AI_GATEWAY_API_KEY?.trim()?{kind:`api-key`,token:process.env.AI_GATEWAY_API_KEY}:{kind:`oidc`,token:await getVercelOidcToken()}}export{resolveGatewayModelCredential};